<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue";
import { LoaderCircle, Pencil, Plus, Save, Search, ToggleLeft, Trash2 } from "lucide-vue-next";
import { ElPagination } from "element-plus";
import { changeProductStatus, createProduct, createProductCapability, deleteProductCapability, getProductCapabilities, getProducts, updateProduct, updateProductCapability, type Product, type ProductCapability, type ProductPayload } from "./api";
import { hasPermission } from "../../auth";
import AppDrawer from "../../components/AppDrawer.vue";
import { getActiveCountries, getActiveCurrencies, type Country, type Currency } from "../master-data/api";

type CapabilityDraft = Omit<ProductCapability, "capabilityId" | "productCode" | "status"> & { capabilityId?: string };
const emit = defineEmits<{ notice: [message: string] }>();
const customerPaymentMethods = [{ value: "CARD", label: "银行卡" }, { value: "APPLE_PAY", label: "Apple Pay" }, { value: "GOOGLE_PAY", label: "Google Pay" }, { value: "ALIPAY", label: "支付宝" }, { value: "WECHAT_PAY", label: "微信支付" }, { value: "BANK_TRANSFER", label: "银行转账" }, { value: "PIX", label: "PIX" }, { value: "UPI", label: "UPI" }];
const channelPaymentMethods = [{ value: "CARD", label: "银行卡通用" }, { value: "CARD_CREDIT", label: "信用卡" }, { value: "CARD_DEBIT", label: "借记卡" }, { value: "APPLE_PAY", label: "Apple Pay" }, { value: "ALIPAY_WAP", label: "支付宝 WAP" }, { value: "WECHAT_H5", label: "微信 H5" }, { value: "BANK_TRANSFER", label: "银行转账" }, { value: "PIX", label: "PIX" }, { value: "UPI", label: "UPI" }];
const products = ref<Product[]>([]), selected = ref<Product | null>(null), loading = ref(false), saving = ref(false), productDrawerOpen = ref(false);
const filters = ref({ status: "", productType: "" });
const page = ref({ current: 1, pageSize: 20, total: 0 });
const blankProduct = (): ProductPayload & { productCode: string } => ({ productCode: "", name: "", productType: "PAYIN", accessMode: "DIRECT", defaultCountry: "US", defaultCurrency: "USD", description: "", statementDescriptor: "" });
const form = ref(blankProduct());
const blankCapability = (): CapabilityDraft => ({ customerPaymentMethod: "CARD", channelPaymentMethod: "CARD", minAmount: 1, maxAmount: 10000, supportsRefund: true });
const capabilityDrafts = ref<CapabilityDraft[]>([]), originalCapabilityIds = ref<string[]>([]);
const countries = ref<Country[]>([]), defaultCurrencies = ref<Currency[]>([]), currenciesByCountry = ref<Record<string, Currency[]>>({});
const activeCapabilities = computed(() => products.value.reduce((sum, item) => sum + item.activeCapabilityCount, 0));
const alert = (error: unknown, fallback: string) => emit("notice", error instanceof Error ? error.message : fallback);

async function load(current = page.value.current) { loading.value = true; try { const result = await getProducts({ page: current, pageSize: page.value.pageSize, ...filters.value }); products.value = result.items; page.value = { current: result.page, pageSize: result.pageSize, total: result.total }; } catch (error) { alert(error, "产品加载失败"); } finally { loading.value = false; } }
function resetFilters() { filters.value = { status: "", productType: "" }; load(1); }
function changePageSize(pageSize: number) { page.value.pageSize = pageSize; load(1); }
async function currenciesFor(country: string) { if (!currenciesByCountry.value[country]) currenciesByCountry.value[country] = await getActiveCurrencies(country); return currenciesByCountry.value[country]; }
async function loadCapabilities(productCode: string) { const result = await getProductCapabilities(productCode, { page: 1, pageSize: 100 }); capabilityDrafts.value = result.items.map(({ capabilityId, productCode: _, status: __, ...item }) => ({ ...item, capabilityId })); originalCapabilityIds.value = result.items.map((item) => item.capabilityId); }
function openProductCreate() { selected.value = null; form.value = blankProduct(); capabilityDrafts.value = [blankCapability()]; originalCapabilityIds.value = []; productDrawerOpen.value = true; }
async function openProductEdit(product: Product) { selected.value = product; form.value = { productCode: product.productCode, name: product.name, productType: product.productType, accessMode: product.accessMode, defaultCountry: product.defaultCountry, defaultCurrency: product.defaultCurrency, description: product.description || "", statementDescriptor: product.statementDescriptor || "" }; try { await loadCapabilities(product.productCode); productDrawerOpen.value = true; } catch (error) { alert(error, "支付方式配置加载失败"); } }
function changeProductType() { if (form.value.productType === "PAYOUT") form.value.accessMode = null; else if (!form.value.accessMode) form.value.accessMode = "DIRECT"; }
function addCapability() { capabilityDrafts.value.push(blankCapability()); }
function removeCapability(index: number) { capabilityDrafts.value.splice(index, 1); }
function validCapabilities() { return capabilityDrafts.value.every((item) => item.customerPaymentMethod.trim() && item.channelPaymentMethod.trim() && item.minAmount > 0 && item.maxAmount >= item.minAmount); }
async function saveProduct() { saving.value = true; try { const product = selected.value ? await updateProduct(selected.value.productCode, form.value) : await createProduct(form.value); const retained = new Set(capabilityDrafts.value.flatMap((item) => item.capabilityId ? [item.capabilityId] : [])); await Promise.all(originalCapabilityIds.value.filter((id) => !retained.has(id)).map((id) => deleteProductCapability(product.productCode, id))); await Promise.all(capabilityDrafts.value.map(({ capabilityId, ...item }) => { const payload = { ...item, customerPaymentMethod: item.customerPaymentMethod.trim(), channelPaymentMethod: item.channelPaymentMethod.trim() }; return capabilityId ? updateProductCapability(product.productCode, capabilityId, payload) : createProductCapability(product.productCode, payload); })); productDrawerOpen.value = false; selected.value = product; await load(); emit("notice", "产品及支付方式已保存"); } catch (error) { alert(error, "产品保存失败"); } finally { saving.value = false; } }
async function toggleProduct(product: Product) { try { Object.assign(product, await changeProductStatus(product.productCode, product.status === "ACTIVE" ? "DISABLED" : "ACTIVE")); emit("notice", "产品状态已更新"); } catch (error) { alert(error, "产品状态更新失败"); } }
watch(() => form.value.defaultCountry, async (countryCode) => { if (!countryCode) return; defaultCurrencies.value = await currenciesFor(countryCode); if (!defaultCurrencies.value.some((item) => item.code === form.value.defaultCurrency)) form.value.defaultCurrency = defaultCurrencies.value[0]?.code || ""; });
onMounted(async () => { await load(); try { countries.value = await getActiveCountries(); defaultCurrencies.value = await currenciesFor(form.value.defaultCountry); } catch (error) { alert(error, "国家与币种基础数据加载失败"); } });
</script>

<template>
  <section class="workspace-panel product-workspace management-list-page">
    <form class="management-filter-form" @submit.prevent="load(1)"><div class="management-filter-fields management-filter-fields-compact"><label class="management-form-item"><span>产品状态</span><select v-model="filters.status"><option value="">全部状态</option><option value="ACTIVE">已启用</option><option value="DISABLED">已停用</option></select></label><label class="management-form-item"><span>产品类型</span><select v-model="filters.productType"><option value="">全部类型</option><option value="PAYIN">收款 PAYIN</option><option value="PAYOUT">出款 PAYOUT</option></select></label></div><div class="management-filter-actions"><button class="outline-btn" type="button" @click="resetFilters">重置</button><button class="primary-btn" type="submit"><Search :size="16" />查询</button><button v-if="hasPermission('product:create')" class="primary-btn" type="button" @click="openProductCreate"><Plus :size="16" />新建产品</button></div></form>
    <div class="management-list-summary"><span>产品列表</span><small>共 {{ page.total }} 个产品 · 启用支付能力 {{ activeCapabilities }}</small></div>
    <div v-if="loading" class="empty"><LoaderCircle class="spin" :size="22" />加载中…</div>
    <div v-else class="table-wrap management-table-wrap"><table class="data-table product-table"><colgroup><col class="product-name-column" /><col class="product-type-column" /><col class="product-market-column" /><col class="product-method-column" /><col class="product-capability-column" /><col class="product-status-column" /><col class="management-actions-column" /></colgroup><thead><tr><th>产品</th><th>类型 / 接入</th><th>默认市场</th><th>已配置对客支付方式</th><th class="num">启用能力</th><th>状态</th><th class="actions">操作</th></tr></thead><tbody><tr v-for="product in products" :key="product.productCode"><td><strong>{{ product.name }}</strong><small class="mono">{{ product.productCode }}</small></td><td><strong>{{ product.productType }}</strong><small>{{ product.accessMode || "不适用" }}</small></td><td><strong>{{ product.defaultCountry }}/{{ product.defaultCurrency }}</strong></td><td>{{ product.supportedPaymentMethods || "未配置" }}</td><td class="num">{{ product.activeCapabilityCount }}</td><td><span class="status-badge" :class="'st-' + product.status.toLowerCase()">{{ product.status === "ACTIVE" ? "已启用" : "已停用" }}</span></td><td class="actions"><div class="management-row-actions"><button v-if="hasPermission('product:update')" class="outline-btn" title="编辑产品和支付方式" @click="openProductEdit(product)"><Pencil :size="16" />编辑</button><button v-if="hasPermission('product:status')" class="outline-btn" title="切换产品状态" @click="toggleProduct(product)"><ToggleLeft :size="16" />{{ product.status === "ACTIVE" ? "停用" : "启用" }}</button></div></td></tr><tr v-if="!products.length"><td colspan="7" class="empty">暂无产品</td></tr></tbody></table></div>
    <div class="management-pagination"><ElPagination background layout="sizes, total, prev, pager, next" :current-page="page.current" :page-size="page.pageSize" :page-sizes="[20, 50, 100]" :total="page.total" :hide-on-single-page="false" @current-change="load" @size-change="changePageSize" /></div>
  </section>
  <AppDrawer v-if="productDrawerOpen" :title="selected ? '编辑产品' : '新建产品'" description="产品与支付方式" @close="productDrawerOpen = false"><form class="product-drawer-form" @submit.prevent="saveProduct"><section class="drawer-section"><h4>基础信息</h4><div class="drawer-form-grid"><label v-if="!selected" class="form-field"><span>产品编码 <b>*</b></span><input v-model="form.productCode" maxlength="64" placeholder="例如 CARD-US-USD" @input="form.productCode = form.productCode.toUpperCase()" /></label><label class="form-field"><span>产品名称 <b>*</b></span><input v-model="form.name" maxlength="128" placeholder="例如 美国卡支付" /></label><label class="form-field"><span>产品类型 <b>*</b></span><select v-model="form.productType" @change="changeProductType"><option value="PAYIN">收款 PAYIN</option><option value="PAYOUT">出款 PAYOUT</option></select></label><label v-if="form.productType === 'PAYIN'" class="form-field"><span>接入模式 <b>*</b></span><select v-model="form.accessMode"><option value="DIRECT">直连 DIRECT</option><option value="AGGREGATED">聚合 AGGREGATED</option></select></label></div></section><section class="drawer-section"><h4>默认市场</h4><div class="drawer-form-grid"><label class="form-field"><span>国家/地区 <b>*</b></span><select v-model="form.defaultCountry"><option v-for="item in countries" :key="item.code" :value="item.code">{{ item.name }} · {{ item.code }}</option></select></label><label class="form-field"><span>币种 <b>*</b></span><select v-model="form.defaultCurrency"><option v-for="item in defaultCurrencies" :key="item.code" :value="item.code">{{ item.name }} · {{ item.code }}</option></select></label></div></section><section class="drawer-section"><div class="section-heading"><div><h4>支付方式配置</h4><small>对客方式用于商户接入，渠道方式用于渠道调用。</small></div><button type="button" class="outline-btn" @click="addCapability"><Plus :size="16" />新增支付方式</button></div><div v-for="(item, index) in capabilityDrafts" :key="item.capabilityId || index" class="capability-editor"><div class="capability-editor-head"><strong>支付方式 {{ index + 1 }}</strong><button type="button" class="icon-btn danger" title="移除支付方式" @click="removeCapability(index)"><Trash2 :size="16" /></button></div><div class="drawer-form-grid"><label class="form-field"><span>对客支付方式 <b>*</b></span><input v-model="item.customerPaymentMethod" list="customer-payment-method-options" maxlength="64" placeholder="输入或选择支付方式编码" /></label><label class="form-field"><span>渠道支付方式 <b>*</b></span><input v-model="item.channelPaymentMethod" list="channel-payment-method-options" maxlength="64" placeholder="输入或选择渠道方式编码" /></label><label class="form-field"><span>最小金额 <b>*</b></span><input v-model.number="item.minAmount" type="number" min="0.01" step="0.01" /></label><label class="form-field"><span>最大金额 <b>*</b></span><input v-model.number="item.maxAmount" type="number" min="0.01" step="0.01" /></label><label class="form-field checkbox-field"><span>退款能力</span><input v-model="item.supportsRefund" type="checkbox" />支持退款</label></div></div><div v-if="!capabilityDrafts.length" class="empty compact-empty">暂未配置支付方式，可直接保存产品或点击新增支付方式。</div></section><section class="drawer-section"><h4>展示信息</h4><div class="drawer-form-grid"><label class="form-field"><span>账单描述符</span><input v-model="form.statementDescriptor" maxlength="22" placeholder="例如 DEMO PAYMENT" /></label><label class="form-field form-field-full"><span>产品描述</span><input v-model="form.description" maxlength="1000" placeholder="填写适用商户、商品或服务说明" /></label></div></section><div class="drawer-actions"><button class="outline-btn" type="button" @click="productDrawerOpen = false">取消</button><button class="primary-btn" type="submit" :disabled="saving || !form.name.trim() || (!selected && !form.productCode.trim()) || !form.defaultCountry || !form.defaultCurrency || (form.productType === 'PAYIN' && !form.accessMode) || !validCapabilities()"><Save :size="16" />{{ saving ? "保存中" : "保存产品" }}</button></div><datalist id="customer-payment-method-options"><option v-for="method in customerPaymentMethods" :key="method.value" :value="method.value">{{ method.label }}</option></datalist><datalist id="channel-payment-method-options"><option v-for="method in channelPaymentMethods" :key="method.value" :value="method.value">{{ method.label }}</option></datalist></form></AppDrawer>
</template>
